import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const e="/img/sum-diff-diagram.svg",l="/img/sum-multi-diagram.svg",o="/img/diff-multi-diagram.svg",x=JSON.parse('{"title":"小学数学应用题三大法宝：和差、和倍、差倍问题全解析","description":"和差、和倍、差倍问题是小学数学中极其重要的应用题基础。本文通过图示法，通俗易懂地拆解这三类问题的解题技巧，助你秒杀应用题！","frontmatter":{"title":"小学数学应用题三大法宝：和差、和倍、差倍问题全解析","date":"2026-01-16T14:00:00.000Z","categories":["数学"],"tags":["小学数学","应用题","和差问题","和倍问题","差倍问题"],"description":"和差、和倍、差倍问题是小学数学中极其重要的应用题基础。本文通过图示法，通俗易懂地拆解这三类问题的解题技巧，助你秒杀应用题！","cover":"/img/math-operators-map.svg","top_img":"/img/math-operators-map.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-word-problems-sum-diff-multi.md","filePath":"posts/primary-math-word-problems-sum-diff-multi.md","lastUpdated":null}'),r={name:"posts/primary-math-word-problems-sum-diff-multi.md"};function p(i,a,c,h,d,g){return n(),t("div",null,[...a[0]||(a[0]=[m('<h1 id="小学数学应用题三大法宝-和差、和倍、差倍问题全解析" tabindex="-1">小学数学应用题三大法宝：和差、和倍、差倍问题全解析 <a class="header-anchor" href="#小学数学应用题三大法宝-和差、和倍、差倍问题全解析" aria-label="Permalink to &quot;小学数学应用题三大法宝：和差、和倍、差倍问题全解析&quot;">​</a></h1><p>在小学数学的广阔海洋里，应用题往往是让孩子们最头疼的部分。但其实，很多看似复杂的题目都万变不离其宗。今天，我们要分享的是应用题中的“三剑客”——<strong>和差问题、和倍问题、差倍问题</strong>。</p><p>掌握了这三大法宝，你就会发现，原本纠缠不清的数量关系，瞬间变得清清楚楚！</p><hr><h2 id="一、-和差问题-已知总和与差值" tabindex="-1">一、 和差问题：已知总和与差值 <a class="header-anchor" href="#一、-和差问题-已知总和与差值" aria-label="Permalink to &quot;一、 和差问题：已知总和与差值&quot;">​</a></h2><h3 id="_1-什么是和差问题" tabindex="-1">1. 什么是和差问题？ <a class="header-anchor" href="#_1-什么是和差问题" aria-label="Permalink to &quot;1. 什么是和差问题？&quot;">​</a></h3><p>已知两个数的<strong>和</strong>与这两个数的<strong>差</strong>，求这两个数各是多少的问题，叫做和差问题。</p><h3 id="_2-核心思维-图示法" tabindex="-1">2. 核心思维：图示法 <a class="header-anchor" href="#_2-核心思维-图示法" aria-label="Permalink to &quot;2. 核心思维：图示法&quot;">​</a></h3><p>想象两条线段，一条长（大数），一条短（小数）。</p><p><img src="'+e+'" alt="和差问题图解"></p><p>如果我们给小数“补上”那个差，它就变得和大数一样长了。此时两个数的总和就变成了 <code>和 + 差</code>，正好是两个大数。 反过来，如果我们把大数“减掉”那个差，它就变得和小数一样短了。此时两个数的总和就变成了 <code>和 - 差</code>，正好是两个小数。</p><h3 id="_3-黄金公式" tabindex="-1">3. 黄金公式 <a class="header-anchor" href="#_3-黄金公式" aria-label="Permalink to &quot;3. 黄金公式&quot;">​</a></h3><ul><li><strong>大数 = (和 + 差) ÷ 2</strong></li><li><strong>小数 = (和 - 差) ÷ 2</strong></li><li>或者：<strong>小数 = 大数 - 差</strong></li></ul><h3 id="_4-经典例题-分书包里的秘密-🎒" tabindex="-1">4. 经典例题：分书包里的秘密 🎒 <a class="header-anchor" href="#_4-经典例题-分书包里的秘密-🎒" aria-label="Permalink to &quot;4. 经典例题：分书包里的秘密 🎒&quot;">​</a></h3><p><strong>题目</strong>：小明和小红一共有 26 本课外书，小明比小红多 4 本。请问两人各有多少本书？</p><p><strong>解析</strong>：</p><ul><li>和 = 26，差 = 4</li><li><strong>大数（小明）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>6</mn><mo>+</mo><mn>4</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>5</mn></mrow><annotation encoding="application/x-tex">(26 + 4) \\div 2 = 15</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">5</span></span></span></span>（本）</li><li><strong>小数（小红）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>2</mn><mn>6</mn><mo>−</mo><mn>4</mn><mo>)</mo><mo>÷</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">(26 - 4) \\div 2 = 11</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mclose">)</span><span class="mbin">÷</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span></span></span></span>（本）</li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>+</mo><mn>1</mn><mn>1</mn><mo>=</mo><mn>2</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">15 + 11 = 26</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span></span></span></span>，正确；<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>5</mn><mo>−</mo><mn>1</mn><mn>1</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">15 - 11 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>，正确！</li></ul><h3 id="💡-避坑小贴士" tabindex="-1">💡 避坑小贴士 <a class="header-anchor" href="#💡-避坑小贴士" aria-label="Permalink to &quot;💡 避坑小贴士&quot;">​</a></h3><p>很多小朋友容易把“和”跟“差”记混。记住：<strong>大数要“加”出头，小数要“减”到底</strong>。</p><hr><h2 id="二、-和倍问题-已知总和与倍数" tabindex="-1">二、 和倍问题：已知总和与倍数 <a class="header-anchor" href="#二、-和倍问题-已知总和与倍数" aria-label="Permalink to &quot;二、 和倍问题：已知总和与倍数&quot;">​</a></h2><h3 id="_1-什么是和倍问题" tabindex="-1">1. 什么是和倍问题？ <a class="header-anchor" href="#_1-什么是和倍问题" aria-label="Permalink to &quot;1. 什么是和倍问题？&quot;">​</a></h3><p>已知两个数的<strong>和</strong>以及它们之间的<strong>倍数关系</strong>，求这两个数各是多少的问题。</p><h3 id="_2-核心思维-份数法-线段图" tabindex="-1">2. 核心思维：份数法（线段图） <a class="header-anchor" href="#_2-核心思维-份数法-线段图" aria-label="Permalink to &quot;2. 核心思维：份数法（线段图）&quot;">​</a></h3><p>我们把小数看作“1 份”，那么大数就是“n 份”。</p><p><img src="'+l+'" alt="和倍问题图解"></p><p>既然总和代表了 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mn>1</mn><mo>+</mo><mi>n</mi><mo>)</mo></mrow><annotation encoding="application/x-tex">(1 + n)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathit">n</span><span class="mclose">)</span></span></span></span> 份，那么 1 份的量（小数）就很简单了。</p><h3 id="_3-黄金公式-1" tabindex="-1">3. 黄金公式 <a class="header-anchor" href="#_3-黄金公式-1" aria-label="Permalink to &quot;3. 黄金公式&quot;">​</a></h3><ul><li><strong>小数（1份量）= 和 ÷ (倍数 + 1)</strong></li><li><strong>大数 = 小数 × 倍数</strong></li><li>或者：<strong>大数 = 和 - 小数</strong></li></ul><h3 id="_4-经典例题-果园里的数学课-🍎" tabindex="-1">4. 经典例题：果园里的数学课 🍎 <a class="header-anchor" href="#_4-经典例题-果园里的数学课-🍎" aria-label="Permalink to &quot;4. 经典例题：果园里的数学课 🍎&quot;">​</a></h3><p><strong>题目</strong>：果园里桃树和梨树一共 120 棵，桃树的棵数是梨树的 3 倍。桃树和梨树各有多少棵？</p><p><strong>解析</strong>：</p><ul><li>把梨树看作 1 份，桃树就是 3 份。</li><li>总份数 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mo>+</mo><mn>3</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">1 + 3 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span> 份。</li><li><strong>1 份量（梨树）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>4</mn><mo>=</mo><mn>3</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120 \\div 4 = 30</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span></span></span></span>（棵）。</li><li><strong>桃树</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>0</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>9</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">30 \\times 3 = 90</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">9</span><span class="mord mathrm">0</span></span></span></span>（棵）。</li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>9</mn><mn>0</mn><mo>+</mo><mn>3</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">90 + 30 = 120</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">9</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>，符合题意。</li></ul><h3 id="💡-避坑小贴士-1" tabindex="-1">💡 避坑小贴士 <a class="header-anchor" href="#💡-避坑小贴士-1" aria-label="Permalink to &quot;💡 避坑小贴士&quot;">​</a></h3><p>找准“1份”是谁非常重要。通常我们把<strong>较小的那个数</strong>看作 1 份，这样算起来最顺手！</p><hr><h2 id="三、-差倍问题-已知差值与倍数" tabindex="-1">三、 差倍问题：已知差值与倍数 <a class="header-anchor" href="#三、-差倍问题-已知差值与倍数" aria-label="Permalink to &quot;三、 差倍问题：已知差值与倍数&quot;">​</a></h2><h3 id="_1-什么是差倍问题" tabindex="-1">1. 什么是差倍问题？ <a class="header-anchor" href="#_1-什么是差倍问题" aria-label="Permalink to &quot;1. 什么是差倍问题？&quot;">​</a></h3><p>已知两个数的<strong>差</strong>以及它们之间的<strong>倍数关系</strong>，求这两个数各是多少的问题。</p><h3 id="_2-核心思维-找准-差-对应的份数" tabindex="-1">2. 核心思维：找准“差”对应的份数 <a class="header-anchor" href="#_2-核心思维-找准-差-对应的份数" aria-label="Permalink to &quot;2. 核心思维：找准“差”对应的份数&quot;">​</a></h3><p>同样把小数看作“1 份”，大数看作“n 份”。</p><p><img src="'+o+'" alt="差倍问题图解"></p><p>这里的关键在于：两个数的差，对应的正是份数的差 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(n - 1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span>。</p><h3 id="_3-黄金公式-2" tabindex="-1">3. 黄金公式 <a class="header-anchor" href="#_3-黄金公式-2" aria-label="Permalink to &quot;3. 黄金公式&quot;">​</a></h3><ul><li><strong>小数（1份量）= 差 ÷ (倍数 - 1)</strong></li><li><strong>大数 = 小数 × 倍数</strong></li><li>或者：<strong>大数 = 小数 + 差</strong></li></ul><h3 id="_4-经典例题-压岁钱大比拼-💰" tabindex="-1">4. 经典例题：压岁钱大比拼 💰 <a class="header-anchor" href="#_4-经典例题-压岁钱大比拼-💰" aria-label="Permalink to &quot;4. 经典例题：压岁钱大比拼 💰&quot;">​</a></h3><p><strong>题目</strong>：哥哥的存款比弟弟多 120 元，哥哥的钱正好是弟弟的 4 倍。兄弟俩各有多少钱？</p><p><strong>解析</strong>：</p><ul><li>把弟弟看作 1 份，哥哥是 4 份。</li><li>份数差 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>−</mo><mn>1</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">4 - 1 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span> 份。</li><li>这 3 份对应的正是 120 元。</li><li><strong>1 份量（弟弟）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120 \\div 3 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>（元）。</li><li><strong>哥哥</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>×</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">40 \\times 4 = 160</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span>（元）。</li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>6</mn><mn>0</mn><mo>−</mo><mn>4</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">160 - 40 = 120</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>，符合题意。</li></ul><h3 id="💡-避坑小贴士-2" tabindex="-1">💡 避坑小贴士 <a class="header-anchor" href="#💡-避坑小贴士-2" aria-label="Permalink to &quot;💡 避坑小贴士&quot;">​</a></h3><p>差倍问题最容易错的地方就是“份数差”。记住：<strong>倍数关系是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.43056em;"></span><span class="strut bottom" style="height:0.43056em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">n</span></span></span></span> 倍，份数差就是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>(</mo><mi>n</mi><mo>−</mo><mn>1</mn><mo>)</mo></mrow><annotation encoding="application/x-tex">(n-1)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mopen">(</span><span class="mord mathit">n</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span></span></span></span></strong>。</p><hr><h2 id="四、-进阶扩展-变式与技巧" tabindex="-1">四、 进阶扩展：变式与技巧 <a class="header-anchor" href="#四、-进阶扩展-变式与技巧" aria-label="Permalink to &quot;四、 进阶扩展：变式与技巧&quot;">​</a></h2><p>在实际考试中，题目往往不会直接告诉你“和”或“差”，需要我们去“找”。</p><h3 id="_1-隐含的-和-或-差" tabindex="-1">1. 隐含的“和”或“差” <a class="header-anchor" href="#_1-隐含的-和-或-差" aria-label="Permalink to &quot;1. 隐含的“和”或“差”&quot;">​</a></h3><ul><li><strong>例</strong>：甲乙两人共有钱 50 元，若甲给乙 5 元，两人钱数相等。求甲乙各有多少钱？</li><li><strong>分析</strong>：甲给乙 5 元后相等，说明甲原来比乙多 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">5 \\times 2 = 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span> 元。这就转化成了“和 = 50，差 = 10”的和差问题。</li></ul><h3 id="_2-数量变化后的-倍数" tabindex="-1">2. 数量变化后的“倍数” <a class="header-anchor" href="#_2-数量变化后的-倍数" aria-label="Permalink to &quot;2. 数量变化后的“倍数”&quot;">​</a></h3><ul><li><strong>例</strong>：小明今年的岁数是小红的 3 倍，4 年后小明比小红大 10 岁。</li><li><strong>分析</strong>：年龄差是永远不变的！所以“差 = 10”。题目又说“今年是 3 倍”，这就是典型的“差倍问题”。</li></ul><hr><h2 id="五、-总结对比表" tabindex="-1">五、 总结对比表 <a class="header-anchor" href="#五、-总结对比表" aria-label="Permalink to &quot;五、 总结对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">问题类型</th><th style="text-align:left;">已知条件</th><th style="text-align:left;">求解目标</th><th style="text-align:left;">核心公式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>和差问题</strong></td><td style="text-align:left;">和、差</td><td style="text-align:left;">大数、小数</td><td style="text-align:left;">大数=(和+差)÷2；小数=(和-差)÷2</td></tr><tr><td style="text-align:left;"><strong>和倍问题</strong></td><td style="text-align:left;">和、倍数</td><td style="text-align:left;">1份量、n份量</td><td style="text-align:left;">1份量(小数)=和÷(倍数+1)</td></tr><tr><td style="text-align:left;"><strong>差倍问题</strong></td><td style="text-align:left;">差、倍数</td><td style="text-align:left;">1份量、n份量</td><td style="text-align:left;">1份量(小数)=差÷(倍数-1)</td></tr></tbody></table><h2 id="六、-总结口诀" tabindex="-1">六、 总结口诀 <a class="header-anchor" href="#六、-总结口诀" aria-label="Permalink to &quot;六、 总结口诀&quot;">​</a></h2><p>为了方便记忆，我们可以总结成一个小口诀：</p><blockquote><p><strong>和差并用求平均，</strong> (和加差除以2是大数) <strong>和倍总份求一份，</strong> (和除以总份数是小数) <strong>差倍差份求一份，</strong> (差除以份数差是小数) <strong>万变不离线段图！</strong></p></blockquote><h2 id="七、-挑战一下-练习题" tabindex="-1">七、 挑战一下（练习题） <a class="header-anchor" href="#七、-挑战一下-练习题" aria-label="Permalink to &quot;七、 挑战一下（练习题）&quot;">​</a></h2><ol><li><strong>(和差)</strong> 两个连续奇数的和是 40，求这两个数。</li><li><strong>(和倍)</strong> 爸爸比小明大 24 岁，今年爸爸的年龄正好是小明的 4 倍，小明今年几岁？</li><li><strong>(差倍)</strong> 学校买来的红气球比蓝气球多 20 个，红气球的个数是蓝气球的 5 倍，红气球有多少个？</li></ol><hr><p><em>提示：解题时记得先画一画线段图哦！如果你有更好的解法，欢迎在评论区分享！</em></p>',68)])])}const b=s(r,[["render",p]]);export{x as __pageData,b as default};
